/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { AnalyzerScreen } from "../../src/analyzer/AnalyzerScreen.js";
import { BlinkComparatorScreen } from "../../src/blink-comparator/BlinkComparatorScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { PhotometryScreen } from "../../src/photometry/PhotometryScreen.js";
import { VariableStarPhotometryPreferencesModel } from "../../src/preferences/VariableStarPhotometryPreferencesModel.js";
import { RegistrationScreen } from "../../src/registration/RegistrationScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();
  const screenNames = stringManager.getScreenNames();

  const preferences = new VariableStarPhotometryPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new RegistrationScreen({
      preferences: preferences,
      // The screen name Property updates automatically when the locale changes
      name: screenNames.registrationStringProperty,
      tandem: Tandem.ROOT.createTandem("registrationScreen"),
    }),
    new BlinkComparatorScreen({
      preferences: preferences,
      // The screen name Property updates automatically when the locale changes
      name: screenNames.blinkComparatorStringProperty,
      tandem: Tandem.ROOT.createTandem("blinkComparatorScreen"),
    }),
    new PhotometryScreen({
      preferences: preferences,
      // The screen name Property updates automatically when the locale changes
      name: screenNames.photometryStringProperty,
      tandem: Tandem.ROOT.createTandem("photometryScreen"),
    }),
    new AnalyzerScreen({
      preferences: preferences,
      // The screen name Property updates automatically when the locale changes
      name: screenNames.analyzerStringProperty,
      tandem: Tandem.ROOT.createTandem("analyzerScreen"),
    }),
  ];

  return { screens, tracked: { stringManager, preferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
